"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Search, X } from "lucide-react";
import type { Lang } from "@/lib/types";

/** Entry of public/search/<lang>.json (generated by scripts/build-content.mjs). */
type Entry = { t: string; p: string; k: string; x: string; i?: string };

const normalize = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[’']/g, " ");

function score(entry: Entry, terms: string[]): number {
  const title = normalize(entry.t);
  const body = normalize(entry.x);
  let total = 0;
  for (const term of terms) {
    if (title.startsWith(term)) total += 6;
    else if (title.includes(` ${term}`)) total += 4;
    else if (title.includes(term)) total += 3;
    else if (body.includes(term)) total += 1;
    else return 0; // every word must match somewhere
  }
  return total;
}

export function HeroSearch({ lang }: { lang: Lang }) {
  const fr = lang === "fr";
  const router = useRouter();
  const [index, setIndex] = useState<Entry[] | null>(null);
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const boxRef = useRef<HTMLDivElement>(null);

  const load = () => {
    if (index) return;
    fetch(`/search/${lang}.json`)
      .then((r) => r.json())
      .then(setIndex)
      .catch(() => setIndex([]));
  };

  const results = useMemo(() => {
    const terms = normalize(query).split(/\s+/).filter((t) => t.length > 1);
    if (!index || terms.length === 0) return [];
    return index
      .map((e) => ({ e, s: score(e, terms) }))
      .filter((r) => r.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, 8)
      .map((r) => r.e);
  }, [index, query]);

  useEffect(() => {
    const onClick = (ev: MouseEvent) => {
      if (!boxRef.current?.contains(ev.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  const go = (entry?: Entry) => {
    if (!entry) return;
    setOpen(false);
    router.push(entry.p);
  };

  return (
    <div ref={boxRef} className="relative mx-auto mt-10 w-full max-w-2xl text-left">
      <form
        role="search"
        onSubmit={(e) => {
          e.preventDefault();
          go(results[active] ?? results[0]);
        }}
        className="flex items-center gap-3 rounded-full border border-white/40 bg-white/95 py-2 pl-6 pr-2 shadow-2xl backdrop-blur-md"
      >
        <Search className="h-5 w-5 shrink-0 text-zinc-500" />
        <input
          type="search"
          value={query}
          onFocus={() => {
            load();
            setOpen(true);
          }}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(0);
            setOpen(true);
          }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              setActive((a) => Math.min(a + 1, results.length - 1));
            } else if (e.key === "ArrowUp") {
              e.preventDefault();
              setActive((a) => Math.max(a - 1, 0));
            } else if (e.key === "Escape") setOpen(false);
          }}
          placeholder={fr ? "Villa, restaurant, spa, article du blog…" : "Villa, restaurant, spa, blog article…"}
          aria-label={fr ? "Rechercher sur le site" : "Search the site"}
          className="min-w-0 flex-1 bg-transparent py-2 text-base text-zinc-900 outline-none placeholder:text-zinc-500 [&::-webkit-search-cancel-button]:hidden"
        />
        {query && (
          <button type="button" onClick={() => setQuery("")} aria-label={fr ? "Effacer" : "Clear"} className="p-1 text-zinc-400 hover:text-zinc-700">
            <X className="h-4 w-4" />
          </button>
        )}
        <button type="submit" className="shrink-0 rounded-full bg-primary px-6 py-3 text-xs font-bold uppercase tracking-widest text-primary-foreground transition-all hover:brightness-110">
          {fr ? "Rechercher" : "Search"}
        </button>
      </form>

      {open && query.trim().length > 1 && (
        <div className="absolute inset-x-0 top-full z-40 mt-3 max-h-[60vh] overflow-y-auto rounded-3xl border border-border/50 bg-white p-2 shadow-2xl">
          {index === null ? (
            <p className="px-4 py-3 text-sm text-zinc-500">{fr ? "Chargement…" : "Loading…"}</p>
          ) : results.length === 0 ? (
            <p className="px-4 py-3 text-sm text-zinc-500">{fr ? "Aucun résultat." : "No results."}</p>
          ) : (
            <ul role="listbox">
              {results.map((r, i) => (
                <li key={r.p} role="option" aria-selected={i === active}>
                  <button
                    type="button"
                    onMouseEnter={() => setActive(i)}
                    onClick={() => go(r)}
                    className={`flex w-full items-center gap-4 rounded-2xl px-3 py-2.5 text-left transition-colors ${i === active ? "bg-primary/10" : "hover:bg-zinc-50"}`}
                  >
                    <span className="h-12 w-12 shrink-0 overflow-hidden rounded-xl bg-secondary/40">
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      {r.i && <img src={r.i} alt="" loading="lazy" className="h-full w-full object-cover" />}
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="block text-[10px] font-bold uppercase tracking-[0.2em] text-primary">{r.k}</span>
                      <span className="block truncate text-sm font-semibold text-zinc-900">{r.t}</span>
                      {r.x && <span className="block truncate text-xs text-zinc-500">{r.x}</span>}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}
